#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "cholesky.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Initial lower-triangular matrix with ones on the diagonal. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite: compute B = A * A^T and
     copy it back into A.

     The computation is written to:
       - use contiguous accesses to A's rows,
       - keep each inner product entirely in registers,
       - minimize traffic to/from B.

     This preserves the mathematical computation:
       B[r][s] = sum_{t=0}^{n-1} A[r][t] * A[s][t]
     and hence the final A, while improving locality. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Local restrict-qualified aliases to help the compiler optimize. */
  DATA_TYPE (*restrict a)[n] = A;
  DATA_TYPE (*restrict b)[n] = POLYBENCH_ARRAY(B);

  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict br = b[r];
      const DATA_TYPE *restrict ar = a[r];

      for (s = 0; s < n; ++s)
        {
          const DATA_TYPE *restrict as = a[s];

          DATA_TYPE sum = (DATA_TYPE)0;
          for (t = 0; t < n; ++t)
            sum += ar[t] * as[t];

          br[s] = sum;
        }
    }

  /* Copy the symmetric positive semi-definite matrix back into A. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      a[r][s] = b[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j <= i; j++) {
    if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
  }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Local restrict-qualified alias for A to aid alias analysis and
     enable more aggressive optimization (e.g., vectorization of
     the inner products). */
  DATA_TYPE (*restrict a)[n] = A;

#pragma scop
  /* Right-looking in-place Cholesky factorization.
     The lower triangle of A becomes the Cholesky factor L. */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict ai = a[i];  /* Current row i */

    /* Start from the current diagonal element. This will be updated
       incrementally as we compute the off-diagonal elements in row i. */
    DATA_TYPE diag = ai[i];

    /* Compute the strictly lower-triangular elements in row i. */
    for (j = 0; j < i; j++) {
      DATA_TYPE *restrict aj = a[j];  /* Row j, used in the inner product */

      /* Schur complement update for A[i][j]:
           ai[j] = (ai[j] - sum_{k=0}^{j-1} ai[k] * aj[k]) / aj[j]; */
      DATA_TYPE sum = ai[j];

      /* Inner product between prefixes of rows i and j. */
      for (k = 0; k < j; k++) {
        sum -= ai[k] * aj[k];
      }

      /* Division by the already computed diagonal element L[j][j]. */
      const DATA_TYPE ajj = aj[j];
      sum /= ajj;

      ai[j] = sum;

      /* Update the diagonal accumulator with L[i][j]^2.
         This is algebraically and numerically equivalent to the
         original separate loop:
           for (k = 0; k < i; ++k)
             A[i][i] -= A[i][k] * A[i][k];
         because:
           - each L[i][j] (stored in ai[j]) appears exactly once,
           - the subtractions are performed in increasing j order
             in both formulations,
           - A[i][i] is not used elsewhere within this i-iteration.

         Thus, the sequence of operations affecting the diagonal element
         is unchanged; only their placement within the i-loop differs. */
      diag -= sum * sum;
    }

    /* Finalize the diagonal entry. */
    ai[i] = SQRT_FUN(diag);
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
