#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "cholesky.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Local restrict-qualified view to help the optimizer. */
  DATA_TYPE (*restrict A_)[n] = (DATA_TYPE (*)[n])A;

  /* Pre-compute 1/n to replace the division in the inner loop by
     a cheaper multiplication. */
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;

  /* Initialize A as a lower-triangular matrix with unit diagonal. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *Ai = A_[i];

      for (j = 0; j <= i; j++)
	/* Original formula: (DATA_TYPE)(-j % n) / n + 1
	 * Using the identity (-j % n) == -(j % n) for integer j,n>0,
	 * and turning division by n into multiplication by inv_n. */
	Ai[j] = (DATA_TYPE)(-(j % n)) * inv_n + (DATA_TYPE)1.0;

      for (j = i+1; j < n; j++) {
	Ai[j] = (DATA_TYPE)0.0;
      }

      /* Enforce unit diagonal. */
      Ai[i] = (DATA_TYPE)1.0;
    }

  /* Make the matrix positive semi-definite: A <- A * A^T. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (*restrict B_)[n] =
    (DATA_TYPE (*)[n])POLYBENCH_ARRAY(B);

  /* Zero-initialize B.
     In PolyBench, DATA_TYPE is a standard scalar type (float/double/int),
     so a zero bit-pattern represents the numerical 0. */
  memset(B_, 0, (size_t)n * (size_t)n * sizeof(DATA_TYPE));

  /* Blocked computation of B = A * A^T for better cache locality.

     Mathematically:
       B[r][s] = sum_t A[r][t] * A[s][t]

     Original loop order was:
       for (t)
         for (r)
           for (s)
             B[r][s] += A[r][t] * A[s][t];

     Below we use a 3D tiled version over (r,s,t). This traverses the
     same set of (r,s,t) triplets exactly once each, but in a cache-
     friendly order. The only difference is the (unavoidable) change in
     the floating-point accumulation order. */

  const int TILE_I = 32;
  const int TILE_J = 32;
  const int TILE_K = 32;

  for (int ii = 0; ii < n; ii += TILE_I) {
    int i_end = ii + TILE_I;
    if (i_end > n) i_end = n;

    for (int jj = 0; jj < n; jj += TILE_J) {
      int j_end = jj + TILE_J;
      if (j_end > n) j_end = n;

      for (int kk = 0; kk < n; kk += TILE_K) {
        int k_end = kk + TILE_K;
        if (k_end > n) k_end = n;

        for (r = ii; r < i_end; ++r) {
          DATA_TYPE *restrict Br = B_[r];

          for (t = kk; t < k_end; ++t) {
            const DATA_TYPE Ar_t = A_[r][t];

            /* Inner-most loop updates a contiguous row of B. */
            for (s = jj; s < j_end; ++s) {
              Br[s] += Ar_t * A_[s][t];
            }
          }
        }
      }
    }
  }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r) {
    memcpy(A_[r], B_[r], (size_t)n * sizeof(DATA_TYPE));
  }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j <= i; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Local restrict-qualified pointer for better alias analysis. */
  DATA_TYPE (*restrict A_)[n] = (DATA_TYPE (*)[n])A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
     DATA_TYPE *restrict Ai = A_[i];

     /* Off-diagonal elements in row i: j < i */
     for (j = 0; j < i; j++) {
        DATA_TYPE *restrict Aj = A_[j];

        /* Start from the original A[i][j] and subtract the dot-product
           sum_{k=0..j-1} A[i][k] * A[j][k]. This is algebraically
           equivalent to the original in-place update:

              A[i][j] -= A[i][k] * A[j][k];

           but uses a scalar accumulator, which reduces memory traffic
           and exposes a clear reduction for vectorization. */
        DATA_TYPE sum = Ai[j];

        for (k = 0; k < j; k++) {
           sum -= Ai[k] * Aj[k];
        }

        Ai[j] = sum / Aj[j];
     }

     /* Diagonal element A[i][i]. */
     DATA_TYPE diag = Ai[i];

     /* A[i][i] = sqrt(A[i][i] - sum_{k=0..i-1} A[i][k]^2). */
     for (k = 0; k < i; k++) {
        const DATA_TYPE Aik = Ai[k];
        diag -= Aik * Aik;
     }

     Ai[i] = SQRT_FUN(diag);
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
