  /* Initial lower-triangular matrix construction. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict Ai = A_[i];

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + (DATA_TYPE)1;

      for (j = i+1; j < n; j++) {
	Ai[j] = (DATA_TYPE)0;
      }

      Ai[i] = (DATA_TYPE)1;
    }

  /* Make the matrix positive semi-definite. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);

  /* Zero-initialize B in a cache-friendly way.
     This preserves semantics because the representation of floating-point
     zero is all-bits-zero. */
  {
    DATA_TYPE *B_base = &B_[0][0];
    size_t total_elems = (size_t)n * (size_t)n;
    memset(B_base, 0, total_elems * sizeof(DATA_TYPE));
  }

  /* Compute B = A * A^T.
     The loop order (t, r, s) is kept identical to the original code to
     preserve the exact accumulation order in floating-point arithmetic. */
  for (t = 0; t < n; ++t)
    {
      for (r = 0; r < n; ++r)
	{
	  const DATA_TYPE Ar_t = A_[r][t];
	  DATA_TYPE *restrict B_row = B_[r];

	  for (s = 0; s < n; ++s)
	    {
