	    }
	}
    }

  /* Copy the positive semi-definite matrix back into A. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict A_row = A_[r];
      const DATA_TYPE *restrict B_row = B_[r];

      for (s = 0; s < n; ++s)
	A_row[s] = B_row[s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


