   including the call and return. */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Local restrict-qualified view of A to improve compiler optimizations. */
  DATA_TYPE (*restrict A_)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
     DATA_TYPE *restrict Ai = A_[i];

     /* Off-diagonal elements in row i (j < i). */
     for (j = 0; j < i; j++) {
        DATA_TYPE *restrict Aj = A_[j];

        /* Keep the running value of A[i][j] in a register to avoid
           repeated memory traffic. The subtraction is performed once
           per k iteration, exactly as in the original code, so the
           floating-point operation order is preserved. */
        DATA_TYPE Aij = Ai[j];

        const DATA_TYPE *restrict Aik = Ai;
        const DATA_TYPE *restrict Ajk = Aj;

        for (k = 0; k < j; k++) {
