  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (*Bbuf)[n] = POLYBENCH_ARRAY(B);

  for (r = 0; r < n; ++r)
  {
    const DATA_TYPE *Ar = A[r];
    for (s = 0; s < n; ++s)
    {
      const DATA_TYPE *As = A[s];
      DATA_TYPE sum = (DATA_TYPE)0;

