   * to the loop indices are preserved:
   *   - For each (i,j), the updates to tmp use k in strictly increasing
   *     order.
   *   - For each diagonal element A[i][i], the subtractions are applied
   *     in increasing k, exactly as in the original code, just via a
   *     local variable instead of the array element.
   */
  for (i = 0; i < _PB_N; i++) {
    /* Pointer to the current row i (L's row).  Marked restrict because
       within this scope we only access this row through Ai, and no other
       restrict-qualified pointer aliases it. */
    DATA_TYPE * __restrict Ai = A[i];

    /* Off-diagonal elements: j < i */
    for (j = 0; j < i; j++) {
      DATA_TYPE * __restrict Aj = A[j];

      /* Start from the initial value A[i][j] and subtract the dot product
         of the already computed part of rows i and j. */
      DATA_TYPE tmp = Ai[j];

      /* Compute: tmp -= sum_{k=0}^{j-1} Ai[k] * Aj[k]; */

      k = 0;
      /* Unrolled loop: preserves k order (0,1,2,3,...) while improving
         instruction-level parallelism. */
      for (; k + 3 < j; k += 4) {
        tmp -= Ai[k]     * Aj[k];
        tmp -= Ai[k + 1] * Aj[k + 1];
        tmp -= Ai[k + 2] * Aj[k + 2];
        tmp -= Ai[k + 3] * Aj[k + 3];
      }
      for (; k < j; ++k) {
        tmp -= Ai[k] * Aj[k];
      }

      /* Divide by the diagonal element A[j][j] (Aj[j]) to get L(i,j). */
      Ai[j] = tmp / Aj[j];
    }

    /* Diagonal element: i == j
       Compute:
         A[i][i] = sqrt( A[i][i] - sum_{k=0}^{i-1} Ai[k]^2 )
     */

    DATA_TYPE diag = Ai[i];

    k = 0;
    /* Again, unrolled accumulation with preserved k order. */
    for (; k + 3 < i; k += 4) {
      DATA_TYPE a0 = Ai[k];
      DATA_TYPE a1 = Ai[k + 1];
      DATA_TYPE a2 = Ai[k + 2];
      DATA_TYPE a3 = Ai[k + 3];

      diag -= a0 * a0;
      diag -= a1 * a1;
      diag -= a2 * a2;
      diag -= a3 * a3;
    }
    for (; k < i; ++k) {
      DATA_TYPE v = Ai[k];
      diag -= v * v;
    }

    Ai[i] = SQRT_FUN(diag);
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
